const MES = {enero:1,febrero:2,marzo:3,abril:4,mayo:5,junio:6,julio:7,agosto:8,septiembre:9,setiembre:9,octubre:10,noviembre:11,diciembre:12};
const mesKey = t => { const l=t.toLowerCase(); const m=Object.keys(MES).find(k=>l.includes(k)); const y=Number((l.match(/\d{2,4}/)||[0])[0]); return (y<100?2000+y:y)*100+(MES[m]||0); };
let contenidos = [];
for (const vr of ($('Cont · Sheets batchGet').first().json.valueRanges || [])) {
  const tab = String(vr.range || '').split('!')[0].replace(/^'|'$/g,'');
  const {hdr, rows} = toObjs(vr.values);
  rows.forEach((r,i) => {
    const anchors = [];
    for (let n=1;n<=10;n++) {
      const a = pick(r,hdr,[`anchor ${n}`,`anchor${n}`,`anchor text ${n}`]);
      const uu = pick(r,hdr,[`url anchor ${n}`,`url ${n}`,`link ${n}`,`url${n}`]);
      const p = pick(r,hdr,[`posicion ${n}`,`pos ${n}`,`ranking ${n}`]);
      if (a || uu) anchors.push({ a, u: uu, p });
    }
    const st = pick(r,hdr,['status','estado','estatus']);
    contenidos.push({
      mes: tab, semana: Number((pick(r,hdr,['semana','week']).match(/\d/)||[0])[0]) || null, ord: i+1,
      keyword: pick(r,hdr,['keyword','kw','palabra clave','keyword principal']),
      tipo: pick(r,hdr,['tipo','type','tipo de pagina']),
      url: pick(r,hdr,['url','link','url destino']),
      texto: pick(r,hdr,['texto','contenido','texto seo']),
      status: st || 'pendiente', listo: /ok|listo|publicado/i.test(st),
      vbEditor: /ok|si|sí/i.test(pick(r,hdr,['vb editor','visto bueno','vb'])) ? 'ok' : 'pendiente',
      comentarioRev: pick(r,hdr,['comentario','comentarios','observacion']),
      anchors, _k: mesKey(tab)
    });
  });
}

// v2: aplicar lo guardado desde el portal (hoja Portal_Estado: texto, status, vbEditor)
try {
  const pe = ($('Cont · Leer Portal_Estado').first().json || {}).values || [];
  const h = (pe[0] || []).map(norm); const ix = k => h.indexOf(norm(k));
  const est = {};
  pe.slice(1).forEach(r => { const id = String(r[ix('id')] || '').trim(); if (id) est[id] = r; });
  contenidos.forEach(x => {
    const r = est[[cliente, x.mes, x.semana, x.url || x.keyword].join('|')];
    if (!r) return;
    const g = k => { const i = ix(k); return i >= 0 ? String(r[i] ?? '').trim() : ''; };
    if (g('texto')) x.texto = g('texto');
    if (g('status')) { x.status = g('status'); x.listo = /ok|listo|publicado/i.test(x.status); }
    if (g('vbEditor')) x.vbEditor = /ok|si|sí/i.test(g('vbEditor')) ? 'ok' : 'pendiente';
  });
} catch (e) {}
contenidos = contenidos.filter(x => x.keyword || x.url)
  .sort((a,b) => b._k-a._k || (b.semana||0)-(a.semana||0) || a.ord-b.ord)   // mes actual→viejo, semana 4→1
  .map(({_k,...x}) => x);
const meses = [...new Set(contenidos.map(x => x.mes))];
return [{ json: { ok: true, rol: u.rol, cliente, meses, defaultMes: meses[0] || null, total: contenidos.length, actualizado: new Date().toISOString(), contenidos } }];

